import { TRPCError } from '@trpc/server';
import { z } from 'zod';

import { recordIdSchema, reviewerSchema, revisionScopeSchema } from '../../contracts/src/interfaces/vocabulary.js';
import { createReviewRuntime } from '../subs/core/src/runtime.js';
import type { ReviewOutcome } from '../subs/core/src/runtime.js';
import type { InspectionPort } from '../subs/core/src/interfaces/port.js';
import type { ProtocolFacilities } from '../../../../../src/interfaces/protocol.js';

/**
 * The review feature's tRPC surface.
 *
 * The factory receives the configured runtime and the inspection port rather
 * than importing either, so the root stays the only place a runtime is created
 * and the only place that decides what satisfies the port. `run` is a mutation
 * because a review is work performed on request, not a value read.
 *
 * This surface has no session of its own: the tRPC transport carries none, so
 * a caller states its scope and its reviewer with every request. The session
 * binding belongs to the MCP surface beside this one.
 */
export function createReviewsRouter(facilities: ProtocolFacilities, port: InspectionPort) {
  const runtime = createReviewRuntime(port);

  return facilities.router({
    run: facilities.procedure
      .input(z.object({ recordId: recordIdSchema, scope: revisionScopeSchema.optional(), reviewer: reviewerSchema }))
      .mutation(({ input }): ReviewOutcome => {
        const outcome = runtime.run(input.recordId, input.scope ?? { kind: 'all' }, input.reviewer);

        if (!outcome) {
          throw new TRPCError({
            code: 'NOT_FOUND',
            message: `No record is recorded under the id ${input.recordId}.`,
          });
        }

        return outcome;
      }),
  });
}

import type { Reviewer, RevisionScope } from '../../contracts/src/interfaces/vocabulary.js';

/**
 * The review-session table.
 *
 * A client that opens an MCP session can bind that session to a revision
 * scope, and every later request of that session is reviewed under it. It
 * binds the session to a reviewer the same way, and every later review of
 * that session is made by that reviewer. The table is the whole of that
 * state: which scope each session is bound to and which binding operation set
 * it, and which reviewer each session is bound to.
 *
 * It is a factory rather than a module-level map so that every instance is
 * explicit. The application creates exactly one, at assembly, and shares it
 * across the per-connection MCP servers; a test creates its own.
 */

/** What one session is currently bound to. */
export interface SessionBinding {
  readonly scope: RevisionScope;
  /**
   * Which binding operation of this table produced it, counting from one.
   * A counter rather than a clock: it makes an invocation snapshot say exactly
   * which binding it used, which a timestamp could not.
   */
  readonly boundAt: number;
}

/** The scope a caller asks a session to be bound to. */
export interface SessionBindingRequest {
  readonly scope: RevisionScope;
}

/** Bindings by session id, with a default for every session that has none. */
export interface SessionTable {
  /** Binds one session and returns the binding that is now in force. */
  bind(sessionId: string | null, binding: SessionBindingRequest): SessionBinding;
  /** The binding in force for one session; the default binding when it has none. */
  resolveBinding(sessionId: string | null): SessionBinding;
  /** Binds one session to a reviewer, replacing the one it had. */
  bindReviewer(sessionId: string | null, reviewer: Reviewer): Reviewer;
  /**
   * The reviewer a session is bound to, or null when nothing bound one. There
   * is no default reviewer: a session that binds none cannot review.
   */
  resolveReviewer(sessionId: string | null): Reviewer | null;
}

/**
 * What an unbound session reviews: the whole recorded chain. `boundAt` is zero
 * because no binding operation produced it.
 */
const defaultBinding: SessionBinding = Object.freeze({
  scope: Object.freeze({ kind: 'all' as const }),
  boundAt: 0,
});

/**
 * A new, empty table. A transport without a session of its own arrives with a
 * null id; that is one key like any other, and it resolves to the default
 * binding until something binds it.
 */
export function createSessionTable(): SessionTable {
  const bindings = new Map<string | null, SessionBinding>();
  const reviewers = new Map<string | null, Reviewer>();
  let bindingCount = 0;

  return {
    bind(sessionId, binding) {
      bindingCount += 1;

      // The table keeps its own frozen copy, so a caller that later changes
      // the object it passed cannot change what a session is bound to.
      const stored: SessionBinding = Object.freeze({
        scope: Object.freeze({ ...binding.scope }),
        boundAt: bindingCount,
      });

      bindings.set(sessionId, stored);

      return stored;
    },

    resolveBinding(sessionId) {
      return bindings.get(sessionId) ?? defaultBinding;
    },

    bindReviewer(sessionId, reviewer) {
      const stored: Reviewer = Object.freeze({ ...reviewer });
      reviewers.set(sessionId, stored);
      return stored;
    },

    resolveReviewer(sessionId) {
      return reviewers.get(sessionId) ?? null;
    },
  };
}

