import { tick } from '../subs/controller/src/controller.js';
import { validateRevisionChain } from '../../validation/src/validate.js';
import type { InspectionPort } from './interfaces/port.js';
import type {
  Finding,
  Observation,
  RecordId,
  Reviewer,
  ReviewStatus,
  RevisionScope,
} from '../../../../contracts/src/interfaces/vocabulary.js';

/**
 * The review runtime: this owner's assembly of its own children.
 *
 * A runtime is built around one inspection port and answers one question —
 * what does reviewing this record produce? It schedules a single task with the
 * rules the validator supplies and hands that task to the controller's tick.
 * Both halves arrive through exposures: `tick` from the controller child,
 * `validateRevisionChain` from a module outside this subtree entirely, relayed
 * down by the review feature above.
 */

/**
 * What one review produced. It is this owner's own type, exposed upward to the
 * adapters that publish it and never downward: the views the feature renders
 * receive values and callbacks instead of the runtime's vocabulary.
 */
export interface ReviewOutcome {
  recordId: RecordId;
  /** Who reviewed it. A review with no reviewer is not a review. */
  reviewer: Reviewer;
  status: ReviewStatus;
  findings: Finding[];
  observations: Observation[];
}

/** A runtime bound to one inspection port. */
export interface ReviewRuntime {
  /**
   * Reviews the scoped part of one record as the given reviewer, or answers
   * `undefined` when the port knows no record with that id. Turning that
   * absence into a protocol error is an adapter's decision, as it is
   * everywhere else in this tree.
   */
  run(recordId: RecordId, scope: RevisionScope, reviewer: Reviewer): ReviewOutcome | undefined;
}

/**
 * Builds a runtime over one port. The port is an argument rather than an
 * import, so nothing here — and nothing in the task or the controller below —
 * ever names the catalog that satisfies it.
 */
export function createReviewRuntime(port: InspectionPort): ReviewRuntime {
  return {
    run(recordId, scope, reviewer) {
      const verdict = tick({ recordId, scope, port, validate: validateRevisionChain });
      return verdict === undefined ? undefined : { ...verdict, reviewer };
    },
  };
}

import { describe, expect, it } from 'vitest';

import { createReviewRuntime } from '../runtime.js';
import { makeCatalogFixture } from '../../../../../catalog/subs/core/src/tests/fixture.js';
import type { InspectionPort } from '../interfaces/port.js';

/**
 * The runtime, its controller and its task, run together over the catalog's
 * own test data.
 *
 * This is the parent-owned integration test: nothing below is substituted.
 * The controller's tick, the task and the validator are the real ones, and the
 * only thing built here is the port, whose data comes from the fixture the
 * catalog exposes to other owners' tests. Ordinary source anywhere in this
 * tree could not import that fixture; this area can, because its profile
 * carries `testing`.
 */

function createFixturePort(): InspectionPort {
  const records = makeCatalogFixture();

  return {
    inspect(recordId, scope, observe) {
      const record = records.find((candidate) => candidate.recordId === recordId);

      if (!record) {
        return undefined;
      }

      const chain =
        scope.kind === 'all'
          ? record.chain
          : record.chain.slice(Math.max(record.chain.length - scope.count, 0));

      observe({ kind: 'inspection-started', message: `${chain.length} revision(s)`, recordId });

      const known = new Set(chain.map((revision) => revision.id));
      const resolvedPredecessors: string[] = [];
      const unresolvedPredecessors: string[] = [];

      for (const revision of chain) {
        const predecessor = revision.predecessor;

        if (predecessor === null) {
          continue;
        }

        if (known.has(predecessor)) {
          resolvedPredecessors.push(predecessor);
        } else {
          unresolvedPredecessors.push(predecessor);
        }
      }

      observe({
        kind: 'inspection-finished',
        message: `${unresolvedPredecessors.length} unresolved predecessor reference(s)`,
        recordId,
      });

      return { recordId, chain, resolvedPredecessors, unresolvedPredecessors, findings: [] };
    },
  };
}

/** The reviewer every review below is made by. */
const reviewer = { id: 'rv-ada', displayName: 'Ada Lovelace', role: 'maintainer' };

describe('createReviewRuntime', () => {
  it('fails the record whose chain names a predecessor it does not contain', () => {
    const outcome = createReviewRuntime(createFixturePort()).run('rec-broken', { kind: 'all' }, reviewer);

    expect(outcome).toEqual({
      recordId: 'rec-broken',
      reviewer,
      status: 'failed',
      findings: [
        {
          code: 'missing-predecessor',
          message: 'Revision rev-2 follows rev-0, which is not a revision of the inspected chain.',
          revisionId: 'rev-2',
        },
      ],
      observations: [
        { kind: 'inspection-started', message: '2 revision(s)', recordId: 'rec-broken' },
        {
          kind: 'inspection-finished',
          message: '1 unresolved predecessor reference(s)',
          recordId: 'rec-broken',
        },
      ],
    });
  });

  it('passes the record with an intact history', () => {
    const outcome = createReviewRuntime(createFixturePort()).run('rec-valid', { kind: 'all' }, reviewer);

    expect(outcome?.status).toBe('passed');
    expect(outcome?.findings).toEqual([]);
    expect(outcome?.observations).toHaveLength(2);
  });

  it('reviews only the scope it was given', () => {
    // The latest revision alone still names `rev-1` as its predecessor, and
    // `rev-1` is not part of what was inspected.
    const outcome = createReviewRuntime(createFixturePort()).run('rec-valid', {
      kind: 'latest',
      count: 1,
    }, reviewer);

    expect(outcome?.status).toBe('failed');
    expect(outcome?.findings.map((finding) => finding.revisionId)).toEqual(['rev-2']);
  });

  it('attributes the outcome to the reviewer it was given, with all three parts', () => {
    const grace = { id: 'rv-grace', displayName: 'Grace Hopper', role: 'auditor' };

    expect(createReviewRuntime(createFixturePort()).run('rec-valid', { kind: 'all' }, grace)?.reviewer).toEqual(grace);
  });

  it('answers with no outcome for a record the port does not know', () => {
    expect(createReviewRuntime(createFixturePort()).run('rec-missing', { kind: 'all' }, reviewer)).toBeUndefined();
  });
});

