 *
 * The loading step is a plain function rather than an effect, which is what
 * lets a Node test drive a real review through a real client and then render
 * what came back.
 */

/**
 * Runs one review, as the given reviewer, and returns exactly what the pure
 * view renders.
 *
 * The client's output type is inferred from the procedure, and the mapping
 * below names none of it: `ReviewOutcome` belongs to the review runtime and
 * stops at the feature that adapts it. What survives that boundary is the
 * neutral vocabulary both shapes are written in.
 */
export async function loadReview(
  client: TRPCClient<AppRouter>,
  recordId: string,
  reviewer: Reviewer,
): Promise<ReviewResultProps> {
  const outcome = await client.reviews.run.mutate({ recordId, reviewer });

  return {
    recordId: outcome.recordId,
    reviewer: outcome.reviewer,
    status: outcome.status,
    findings: outcome.findings,
    observations: outcome.observations,
  };
}

interface ReviewPanelProps {
  client: TRPCClient<AppRouter>;
  recordId: string;
  /** Who the reviews this panel runs are made by. */
  reviewer: Reviewer;
}

/** A Review button for one record, and whatever the review answered. */
export function ReviewPanel({ client, recordId, reviewer }: ReviewPanelProps): ReactElement {
  const [result, setResult] = useState<ReviewResultProps | null>(null);
  const [failure, setFailure] = useState<string | null>(null);
  const [running, setRunning] = useState(false);

  const review = (): void => {
    setRunning(true);
    setFailure(null);

    loadReview(client, recordId, reviewer).then(
      (loaded) => {
        setResult(loaded);
        setRunning(false);
      },
      (reason: unknown) => {
        setFailure(reason instanceof Error ? reason.message : String(reason));
        setRunning(false);
      },
    );
  };

  return (
    <div className="review-panel">
      <button type="button" className="review-panel__run" onClick={review} disabled={running}>
        {running ? 'Reviewing...' : 'Review'}
      </button>

      {failure !== null && (
        <p className="review-panel__failure" role="alert">
          The review could not be run: {failure}
        </p>
      )}

      {result !== null && <ReviewResult {...result} />}
    </div>
  );
}

import { renderToStaticMarkup } from 'react-dom/server';
import { describe, expect, it } from 'vitest';

import { createTestSystem } from '../../../../../../../../src/tests/setup.js';
import { ReviewPanel, loadReview } from '../review-panel.js';
import { ReviewResult } from '../../subs/pure-ui/src/review-result.js';

/** The reviewer every review in this file is made by. */
const reviewer = { id: 'rv-ada', displayName: 'Ada Lovelace', role: 'maintainer' };

/**
 * The connected view, driven against the configured system.
 *
 * The client below is the real one, over the real assembled router, so these
 * are the answers the listener gives. Rendering is static markup under Node:
 * this owner's test area carries `ui` and `dispatch` and never `browser`,
 * which is exactly the combination a Node test of a browser component needs.
 */

describe('loadReview', () => {
  it('maps a failed review onto the props the pure view declares', async () => {
    const { client } = createTestSystem();

    const props = await loadReview(client, 'rec-broken', reviewer);

    expect(props).toEqual({
      recordId: 'rec-broken',
      reviewer,
      status: 'failed',
      findings: [
        {
          code: 'missing-predecessor',
          message: 'Revision rev-2 follows rev-0, which is not a revision of the inspected chain.',
          revisionId: 'rev-2',
        },
      ],
      observations: [
        {
          kind: 'inspection-started',
          message: 'Inspecting 2 of 2 revisions',
          recordId: 'rec-broken',
        },
        {
          kind: 'inspection-finished',
          message: '1 predecessor reference(s) resolved to no revision',
          recordId: 'rec-broken',
        },
      ],
    });

    expect(renderToStaticMarkup(<ReviewResult {...props} />)).toContain(
      'rev-2 — missing-predecessor',
    );
  });

  it('maps a passed review the same way', async () => {
    const { client } = createTestSystem();

    const props = await loadReview(client, 'rec-valid', reviewer);

    expect(props.recordId).toBe('rec-valid');
    expect(props.status).toBe('passed');
    expect(props.findings).toEqual([]);
    expect(props.observations.map((observation) => observation.kind)).toEqual([
      'inspection-started',
      'inspection-finished',
    ]);

    expect(renderToStaticMarkup(<ReviewResult {...props} />)).toContain('No findings.');
    expect(renderToStaticMarkup(<ReviewResult {...props} />)).toContain('Reviewed by Ada Lovelace, maintainer');
  });
});

describe('ReviewPanel', () => {
  it('offers the review before anything has been run', () => {
    const { client } = createTestSystem();

    const markup = renderToStaticMarkup(<ReviewPanel client={client} recordId="rec-broken" reviewer={reviewer} />);

    expect(markup).toContain('>Review</button>');
    expect(markup).not.toContain('missing-predecessor');
  });
});

