import type { ReactElement } from 'react';

import { StatusBadge } from '../../../../../../shared-ui/src/status-badge.js';
import { formatFinding } from './format.js';
import styles from './review-result.module.css';
import type {
  Finding,
  Observation,
  RecordId,
  Reviewer,
  ReviewStatus,
} from '../../../../../../contracts/src/interfaces/vocabulary.js';

/**
 * A finished review, rendered.
 *
 * The props are this owner's own type, written in the neutral vocabulary every
 * owner in the tree shares. That is what keeps the review runtime's own
 * `ReviewOutcome` out of the views: the outcome stops at the feature that
 * adapts it, and the connected panel above maps whatever the API answered onto
 * the shape declared here.
 */

/** What this view renders. Every member is neutral vocabulary. */
export interface ReviewResultProps {
  recordId: RecordId;
  /** Who made the review, shown above the verdict. */
  reviewer: Reviewer;
  status: ReviewStatus;
  findings: Finding[];
  observations: Observation[];
}

/** One review's reviewer, its verdict, its findings, and what the inspection observed. */
export function ReviewResult({
  recordId,
  reviewer,
  status,
  findings,
  observations,
}: ReviewResultProps): ReactElement {
  return (
    <section className={styles.result}>
      <p className={styles.reviewer} data-reviewer={reviewer.id}>
        Reviewed by {reviewer.displayName}, {reviewer.role}
      </p>
      <h3 className={styles.heading}>
        Review of {recordId} <StatusBadge status={status} />
      </h3>

      {findings.length === 0 ? (
        <p>No findings.</p>
      ) : (
        <ul className={styles.findings}>
          {findings.map((finding, index) => (
            <li key={`${index}-${finding.code}`}>{formatFinding(finding)}</li>
          ))}
        </ul>
      )}

      <ul className={styles.observations}>
        {observations.map((observation, index) => (
          <li key={`${index}-${observation.kind}`}>
            {observation.kind}: {observation.message}
          </li>
        ))}
      </ul>
    </section>
  );
}

import { renderToStaticMarkup } from 'react-dom/server';
import { describe, expect, it } from 'vitest';

import { ReviewResult } from '../review-result.js';

/**
 * The view, checked as static markup against props built here.
 *
 * The props are the ones this owner declares, so a test needs neither a review
 * runtime nor a client to exercise the view: what the API answers is the
 * connected panel's problem, one module up.
 */

/** The reviewer every review in this file was made by. */
const reviewer = { id: 'rv-ada', displayName: 'Ada Lovelace', role: 'maintainer' };

describe('ReviewResult', () => {
  it('renders the verdict, every finding and every observation', () => {
    const markup = renderToStaticMarkup(
      <ReviewResult
        recordId="rec-broken"
        reviewer={reviewer}
        status="failed"
        findings={[
          {
            code: 'missing-predecessor',
            message: 'Revision rev-2 follows rev-0, which is not a revision of the inspected chain.',
            revisionId: 'rev-2',
          },
        ]}
        observations={[
          { kind: 'inspection-started', message: 'Inspecting 2 of 2 revisions', recordId: 'rec-broken' },
        ]}
      />,
    );

    expect(markup).toContain('rec-broken');
    expect(markup).toContain('data-status="failed"');
    expect(markup).toContain('rev-2 — missing-predecessor');
    expect(markup).toContain('inspection-started: Inspecting 2 of 2 revisions');
  });

  it('shows the reviewer\'s display name and role above the verdict', () => {
    const markup = renderToStaticMarkup(
      <ReviewResult recordId="rec-valid" reviewer={reviewer} status="passed" findings={[]} observations={[]} />,
    );

    expect(markup).toContain('Reviewed by Ada Lovelace, maintainer');
    expect(markup).toContain('data-reviewer="rv-ada"');
    expect(markup.indexOf('Ada Lovelace')).toBeLessThan(markup.indexOf('data-status="passed"'));
  });

  it('says so when a review found nothing to report', () => {
    const markup = renderToStaticMarkup(
      <ReviewResult recordId="rec-valid" reviewer={reviewer} status="passed" findings={[]} observations={[]} />,
    );

    expect(markup).toContain('No findings.');
    expect(markup).toContain('data-status="passed"');
  });
});
